const documents = [];
for (const item of $input.all()) {
  const value = item.json;
  if (Array.isArray(value)) documents.push(...value);
  else if (Array.isArray(value?.body?.documents)) documents.push(...value.body.documents);
  else if (Array.isArray(value?.documents)) documents.push(...value.documents);
  else if (Array.isArray(value?.data?.documents)) documents.push(...value.data.documents);
}
const replaceAll = $input.all().some((item) => item.json?.body?.replace_all === true || item.json?.replace_all === true || item.json?.data?.replace_all === true);
if (!replaceAll) throw new Error('repository index requires replace_all=true');
if (!documents.length) throw new Error('repository index payload must contain documents');
const seen = new Set();
const output = [];
for (const document of documents) {
  const sourceType = String(document?.source_type ?? '').trim().toLowerCase();
  const externalId = String(document?.external_id ?? '').trim();
  const title = String(document?.title ?? '').trim();
  const content = String(document?.content ?? '').replace(/\r\n/g, '\n').trim();
  if (sourceType !== 'repo' || !externalId || !title || !content || content.length > 200000) continue;
  if (seen.has(externalId)) continue;
  seen.add(externalId);
  output.push({json:{
    source_type: 'repo', external_id: externalId, title: title.slice(0, 200),
    collection: String(document.collection || 'repositorio'), content,
    canonical_url: String(document.canonical_url || ''),
    metadata: document.metadata && typeof document.metadata === 'object' ? document.metadata : {}
  }});
}
if (!output.length) throw new Error('repository index payload contained no valid documents');
return output;

const output = [];
for (const item of $input.all()) {
  const source = item.json;
  const text = String(source.content || '').trim();
  const maxChars = 1400;
  const overlap = 220;
  let start = 0;
  let index = 0;
  while (start < text.length) {
    let end = Math.min(start + maxChars, text.length);
    if (end < text.length) {
      const boundary = Math.max(text.lastIndexOf('\n\n', end), text.lastIndexOf('\n', end),
        text.lastIndexOf('. ', end), text.lastIndexOf(' ', end));
      if (boundary > start + 450) end = boundary + 1;
    }
    const content = text.slice(start, end).trim();
    if (content) {
      output.push({json:{
        document_id:source.document_id, source_type:source.source_type, external_id:source.external_id,
        title:source.title, collection:source.collection, canonical_url:source.canonical_url, content,
        chunk_index:index, token_count:Math.ceil(content.split(/\s+/).filter(Boolean).length * 1.3),
        metadata:{...(source.metadata || {}), chunk_index:index}
      }});
      index++;
    }
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1);
  }
}
return output;

const model = $('Configuración').first().json.embedding_model;
const chunks = $('Trocear documento').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const raw = items[i].json;
  let vector = raw;
  if (Array.isArray(raw) && Array.isArray(raw[0])) vector = raw[0];
  if (raw && Array.isArray(raw.embedding)) vector = raw.embedding;
  if (!Array.isArray(vector) || vector.length !== 384) {
    throw new Error('Embedding dimension mismatch: expected 384, received ' +
      (Array.isArray(vector) ? vector.length : typeof vector));
  }
  const source = (chunks[i] && chunks[i].json) ? chunks[i].json : items[i].json;
  out.push({ json: { ...source, embedding_model: model, embedding: vector } });
}
return out;

const documents = new Map();
for (const item of $input.all()) {
  const documentId = item.json.document_id;
  const chunkIndex = Number(item.json.chunk_index);
  if (!documentId || !Number.isInteger(chunkIndex)) continue;
  const current = documents.get(documentId);
  documents.set(documentId, Math.max(current ?? -1, chunkIndex));
}
return [...documents.entries()].map(([document_id, last_chunk_index]) => ({
  json: { document_id, keep_from_chunk_index: last_chunk_index + 1 }
}));

const external_ids = [...new Set($input.all()
  .map((item) => String(item.json.external_id || '').trim())
  .filter(Boolean))];
if (!external_ids.length) throw new Error('repository cleanup received no external ids');
return [{json:{external_ids_text: external_ids.join('\n')}}];
